    16→// ========================================
    17→// Query Keys
    18→// ========================================
    19→
    20→export const analysisKeys = {
    21→    all: ['analysis'] as const,
    22→    dictionaries: () => [...analysisKeys.all, 'dictionaries'] as const,
    23→    dictionaryList: (type: DictionaryType, cursor?: string | null, search?: string, sortType?: SortType) =>
    24→        [...analysisKeys.dictionaries(), type, {cursor, search, sortType}] as const,
    25→    dictionaryOverview: () => [...analysisKeys.all, 'overview'] as const,
    26→};
    27→
    28→// ========================================
    29→// Dictionary List Hooks (Cursor-based)
    30→// ========================================
    31→
    32→export type SortType = 'UPDATED' | 'KEYWORD';
    33→
    34→interface DictionaryListParams {
    35→    type: DictionaryType;
    36→    cursor?: string | null;
    37→    pageSize?: number;
    38→    search?: string;
    39→    searchField?: 'all' | 'keyword' | 'value';
    40→    wordMatch?: boolean;
    41→    sortType?: SortType;
    42→}
    43→
    44→export function useDictionaries(params: DictionaryListParams) {
    45→    const {type, cursor = null, pageSize = 20, search, wordMatch = false, sortType = 'UPDATED'} = params;
    46→
    47→    return useQuery({
    48→        queryKey: analysisKeys.dictionaryList(type, cursor, search, sortType),
    49→        queryFn: async (): Promise<CursorPaginatedResponse<Dictionary>> => {
    50→            // If search is provided, use search endpoint (returns array)
    51→            if (search && search.trim()) {
    52→                const response = await apiClient.get<BackendDictionary[]>(
    53→                    `/api/v1/dictionary/${type}/search`,
    54→                    {
    55→                        params: {
    56→                            word: search,
    57→                            isMatch: wordMatch,
    58→                        },
    59→                    }
    60→                );
    61→                // Convert search results to cursor response format (flat structure)
    62→                const items = response.data;
    63→                return {
    64→                    items: items.map((item) => ({
    65→                        id: item.id,
    66→                        type: item.type,
    67→                        keyword: item.keyword,
    68→                        value: item.value ?? '',
    69→                        createdAt: item.createdTime,
    70→                        updatedAt: item.updatedTime,
    71→                    })),
    72→                    total: items.length,
    73→                    nextCursor: null,
    74→                    hasNext: false,
    75→                };
    76→            }
    77→
    78→            // Cursor-based list endpoint - avoids ES from+size 10,000 limit
    79→            const response = await apiClient.get<BackendCursorResponse>(
    80→                `/api/v1/dictionary/${type}`,
    81→                {
    82→                    params: {
    83→                        size: pageSize,
    84→                        sort: sortType,
    85→                        ...(cursor && {cursor}),
    86→                    },
    87→                }
    88→            );
    89→            return mapCursorDictionaryResponse(response.data);
    90→        },
    91→        staleTime: 30000, // 30 seconds
    92→    });
    93→}
    94→
    95→// ========================================
    96→// Dictionary CRUD Hooks
    97→// ========================================
    98→
    99→interface CreateDictionaryParams {
   100→    type: DictionaryType;
   101→    keyword?: string | null;
   102→    value?: string | null;
   103→}
   104→
   105→export function useCreateDictionary() {
   106→    const queryClient = useQueryClient();
   107→
   108→    return useMutation({
   109→        mutationFn: async (params: CreateDictionaryParams) => {
   110→            const response = await apiClient.post(
   111→                '/api/v1/dictionary',
   112→                {
   113→                    keyword: params.keyword,
   114→                    type: params.type,
   115→                    value: params.value,
   116→                }
   117→            );
   118→            return response.data;
   119→        },
   120→        onSuccess: (_, variables) => {
   121→            queryClient.invalidateQueries({
   122→                queryKey: analysisKeys.dictionaryList(variables.type),
   123→            });
   124→        },
   125→    });
   126→}
   127→
   128→interface UpdateDictionaryParams {
   129→    type: DictionaryType;
   130→    id: string;
   131→    keyword?: string | null;
   132→    value?: string | null;
   133→}
   134→
   135→export function useUpdateDictionary() {
   136→    const queryClient = useQueryClient();
   137→
   138→    return useMutation({
   139→        mutationFn: async (params: UpdateDictionaryParams) => {
   140→            const response = await apiClient.put(
   141→                `/api/v1/dictionary/${params.id}`,
   142→                {
   143→                    keyword: params.keyword ?? '',
   144→                    type: params.type,
   145→                    value: params.value,
   146→                }
   147→            );
   148→            return response.data;
   149→        },
   150→        onSuccess: (_, variables) => {
   151→            queryClient.invalidateQueries({
   152→                queryKey: analysisKeys.dictionaryList(variables.type),
   153→            });
   154→        },
   155→    });
   156→}
   157→
   158→interface DeleteDictionaryParams {
   159→    type: DictionaryType;
   160→    ids: string[];
   161→}
   162→
   163→export function useDeleteDictionary() {
   164→    const queryClient = useQueryClient();
   165→
   166→    return useMutation({
   167→        mutationFn: async (params: DeleteDictionaryParams) => {
   168→            // Backend only supports single delete, so we delete in parallel
   169→            await Promise.all(
   170→                params.ids.map(id =>
   171→                    apiClient.delete(`/api/v1/dictionary/${id}`)
   172→                )
   173→            );
   174→        },
   175→        onSuccess: (_, variables) => {
   176→            queryClient.invalidateQueries({
   177→                queryKey: analysisKeys.dictionaryList(variables.type),
   178→            });
   179→        },
   180→    });
   181→}
   182→
   183→// ========================================
   184→// Dictionary Overview Hook
   185→// ========================================
   186→
   187→export function useDictionaryOverview() {
   188→    return useQuery({
   189→        queryKey: analysisKeys.dictionaryOverview(),
   190→        queryFn: async (): Promise<DictionaryOverviewResponse> => {
   191→            const response = await apiClient.get<DictionaryOverviewResponse>(
   192→                '/api/v1/dictionary/last-modified'
   193→            );
   194→            return response.data;
   195→        },
   196→        staleTime: 30000, // 30 seconds
   197→    });
   198→}
   199→
   200→// ========================================
   201→// Dictionary Compile Hook
   202→// ========================================
   203→
   204→interface CompileDictionaryParams {
   205→    types: DictionaryType[];
   206→}
   207→
   208→export function useCompileDictionary() {
   209→    const queryClient = useQueryClient();
   210→
   211→    return useMutation({
   212→        mutationFn: async (params: CompileDictionaryParams): Promise<CompileResult[]> => {
   213→            const {types} = params;
   214→
   215→            // If all 8 types are selected, use the bulk compile endpoint
   216→            if (types.length === 8) {
   217→                const response = await apiClient.post<CompileResult[]>(
   218→                    '/api/v1/dictionary/compile'
   219→                );
   220→                return response.data;
   221→            }
   222→
   223→            // Otherwise, compile each type individually in parallel
   224→            const results = await Promise.all(
   225→                types.map(async (type) => {
   226→                    const response = await apiClient.post<CompileResult>(
   227→                        `/api/v1/dictionary/compile/${type}`
   228→                    );
   229→                    return response.data;
   230→                })
   231→            );
   232→            return results;
   233→        },
   234→        onSuccess: () => {
   235→            // Invalidate overview to refresh lastModified times
   236→            queryClient.invalidateQueries({
   237→                queryKey: analysisKeys.dictionaryOverview(),
   238→            });
   239→        },
   240→    });
   241→}
